/* A deletion retires a source only after a reviewed transfer. */
const CicluzPreservation=(()=>{
function choose({name,candidates,onCommit}){
 const dialog=document.createElement('dialog');dialog.className='transfer-dialog';const form=document.createElement('form');const title=document.createElement('h3');title.textContent='Transferir antes de excluir';const help=document.createElement('p');help.textContent='Escolha para onde transferir as informações de “'+name+'”. A origem será arquivada e o histórico da transferência será preservado.';const label=document.createElement('label');label.textContent='Destino';const select=document.createElement('select');select.required=true;select.setAttribute('aria-label','Destino da transferência');select.add(new Option('Selecione o destino',''));candidates.forEach((c,i)=>select.add(new Option(c.label,String(i))));label.append(select);const review=document.createElement('p');review.setAttribute('role','status');const actions=document.createElement('div');actions.className='actions';const submit=document.createElement('button');submit.type='submit';submit.className='btn';submit.textContent='Continuar';const cancel=document.createElement('button');cancel.type='button';cancel.className='btn secondary';cancel.textContent='Cancelar';cancel.onclick=()=>dialog.close();actions.append(submit,cancel);let confirmed=false;select.onchange=()=>{confirmed=false;submit.textContent='Continuar';review.textContent=''};if(!candidates.length){help.textContent='Cadastre outro destino compatível antes de excluir. A origem e todas as suas informações serão mantidas.';select.disabled=true;submit.disabled=true}form.append(title,help,label,review,actions);form.onsubmit=e=>{e.preventDefault();if(select.value==='')return;const dest=candidates[Number(select.value)];if(!confirmed){confirmed=true;review.textContent='Confirmar transferência de “'+name+'” para “'+dest.label+'” e arquivar a origem?';submit.textContent='Confirmar transferência';return}try{if(onCommit(dest)===false){review.textContent='Não foi possível concluir. A origem foi mantida. Feche e tente novamente.';submit.disabled=true;select.disabled=true;return}dialog.close()}catch{review.textContent='Não foi possível concluir. A origem foi mantida.'}};dialog.append(form);document.body.append(dialog);dialog.onclose=()=>dialog.remove();dialog.showModal();select.focus()
}
function record(source,target,extra={}){return {...extra,date:new Date().toISOString(),sourceId:source.id,sourceName:source.name,targetId:target.id,targetName:target.name,sourceSnapshot:structuredClone(source)}}
function history(records){const d=document.createElement('dialog');d.className='transfer-dialog';const h=document.createElement('h3');h.textContent='Histórico de transferências';d.append(h);if(!records.length){const p=document.createElement('p');p.textContent='Nenhuma transferência registrada.';d.append(p)}for(const r of [...records].reverse()){const row=document.createElement('details');const title=document.createElement('summary');title.textContent=r.sourceName+' → '+r.targetName+' · '+new Date(r.date).toLocaleString('pt-BR');const info=document.createElement('p');const names=[];const walk=n=>{names.push(n.name);(n.children||[]).forEach(walk)};walk(r.sourceSnapshot);info.textContent='Origem preservada: '+names.join(' / ');row.append(title,info);d.append(row)}const close=document.createElement('button');close.type='button';close.className='btn';close.textContent='Fechar';close.onclick=()=>d.close();d.append(close);document.body.append(d);d.onclose=()=>d.remove();d.showModal()}
return {choose,record,history};
})();
